import{_ as o,C as t,o as i,c as d,E as a,a2 as c}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"样本复制一遍，聚合效率为何减半？","description":"","frontmatter":{"title":"样本复制一遍，聚合效率为何减半？","date":"2026-10-22","column":"open-source-engineering","category":"daily","article_type":"research-note","edition":"research-center","research_question":"缺失答案和样本数为何会改变同一评分契约下的结果？（Why can missing answers and sample count change scoring outcomes?）","summary":"原源码的合成探针显示，条件平均分与总通信量的组合会产生样本数依赖；影响论文表格的幅度仍未知。","sources":"MASBench paper and pinned companion code; 2026-10-22 internal scorer probe","pageClass":"runtime-v6-article","item_id":"SIG-20261022-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-22-sig-20261022-004-2026-10-22-scoring-denominator-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-22-scoring-denominator.md","filePath":"zh/engineering/2026-10-22-scoring-denominator.md","lastUpdated":1792681615000}'),s={name:"zh/engineering/2026-10-22-scoring-denominator.md"};function l(h,e,p,b,g,m){const r=t("ArticleCover"),n=t("ArticleTableScroll");return i(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-10-22-sig-20261022-004-2026-10-22-scoring-denominator-cover.png",kicker:"研究成果",title:"样本复制一遍，聚合效率为何减半？",summary:"原源码的合成探针显示，条件平均分与总通信量的组合会产生样本数依赖；影响论文表格的幅度仍未知。",version:"2026-10-22",languageHref:"/en/engineering/2026-10-22-scoring-denominator",languageLabel:"English"}),a(n,{language:"zh"}),e[0]||(e[0]=c('<h1 id="样本复制一遍-聚合效率为何减半" tabindex="-1">样本复制一遍，聚合效率为何减半？ <a class="header-anchor" href="#样本复制一遍-聚合效率为何减半" aria-label="Permalink to &quot;样本复制一遍，聚合效率为何减半？&quot;">​</a></h1><p>把一组人工评分记录原样复制一次，平均质量和平均通信量都没变，聚合效率却从 2.5 降到 1.25。这是本次内部评分探针的结果，不是真实智能体变慢。对复现多智能体评测的工程师，先固定缺失处理、分词与聚合分母，才能判断两个“效率”是否真的可比。这篇札记只交付这一项核对方法。</p><h2 id="变化发生在分母" tabindex="-1">变化发生在分母 <a class="header-anchor" href="#变化发生在分母" aria-label="Permalink to &quot;变化发生在分母&quot;">​</a></h2><p>MASBench（多智能体协作评测基准）的固定源码，用平均 F1（词元重合的精确率与召回率调和平均分）除以所有样本的总通信量，再乘以 1000，得到该实现的聚合效率。它不是把每个样本的效率分别求平均。<a href="https://github.com/BUPT-GAMMA/MASBench/blob/c0301a650db95958924bb080192c09fef39389a5/Reasoning/src/run_asymmetric_agents.py" target="_blank" rel="noreferrer">固定聚合源码</a></p><p>同日分析阶段执行了原始评分函数及去除公共缩进后的原始聚合语句。下面列出已有内部实验中的人工记录；每条记录的人工通信量均为 100：</p><table tabindex="0"><thead><tr><th>合成输入</th><th>平均分</th><th>平均通信量</th><th>聚合效率</th></tr></thead><tbody><tr><td>一个满分答案</td><td>1</td><td>100</td><td>10</td></tr><tr><td>满分、零分各一个</td><td>0.5</td><td>100</td><td>2.5</td></tr><tr><td>上一组复制一次，共四条</td><td>0.5</td><td>100</td><td>1.25</td></tr><tr><td>满分、缺失各一个</td><td>1</td><td>100</td><td>5</td></tr></tbody></table><p>来源：2026-10-22 内部隔离源码探针；通信量是人工设定值，不是模型实测用量。第三行的总通信量由 200 变为 400，平均分仍为 0.5，因此结果减半。这里变化的是统计样本数；没有任何依据把它解释成协作机制退化。</p><p>对于固定样本数的既定用途，这个聚合量可以有自己的解释。问题出现在跨样本数比较时：如果分子是均值，分母却是总量，样本数就进入了量尺。应先检查使用目的和分母，再决定能否直接比较；本篇不推断它改变了真实算法排名。</p><h2 id="缺失答案改变了-平均-的对象" tabindex="-1">缺失答案改变了“平均”的对象 <a class="header-anchor" href="#缺失答案改变了-平均-的对象" aria-label="Permalink to &quot;缺失答案改变了“平均”的对象&quot;">​</a></h2><p>第四行比样本复制更隐蔽。已读运行器源码将缺失答案记为无评分，平均分计算时过滤这些记录，但通信量仍纳入总量。因此，一个满分加一个缺失答案，当前聚合得到的平均分为 1；如果按论文附录所述把缺失答案算零，显式对照模型会得到 0.5。<a href="https://arxiv.org/html/2610.04672" target="_blank" rel="noreferrer">论文评分附录</a></p><p>后一个值来自对论文规则的明确模型，不是完整论文评测程序的复现。它用于说明两种合同的不同：只在有答案的样本上平均，回答的是条件质量；把缺失记为零，还纳入了覆盖损失。报告条件质量时，应同时给出回答覆盖与样本总数，不能让一个漂亮均值掩盖它的适用对象。</p><h2 id="同名指标也可能采用不同分词" tabindex="-1">同名指标也可能采用不同分词 <a class="header-anchor" href="#同名指标也可能采用不同分词" aria-label="Permalink to &quot;同名指标也可能采用不同分词&quot;">​</a></h2><p>内部探针还执行了固定源码的归一化与评分函数。人工文本“red-blue”与“red blue”得到零分，因为前者删除标点后成为一个连写词元，后者保留两个词元；“the cat”与“cat”得到满分，因为冠词被删除。这些不是自然语言推理测试，而是字符串处理的控制例子。<a href="https://github.com/BUPT-GAMMA/MASBench/blob/c0301a650db95958924bb080192c09fef39389a5/Reasoning/src/metrics.py" target="_blank" rel="noreferrer">固定评分源码</a></p><p>论文所述的边界切分与冠词保留规则，和当前检查的实现不同。仓库说明已经提示遗留评分约定；这不是新发现的未公开漏洞。<a href="https://github.com/BUPT-GAMMA/MASBench/blob/c0301a650db95958924bb080192c09fef39389a5/README.md" target="_blank" rel="noreferrer">固定版本仓库说明</a> 因此，“使用同一个指标名”还不够，必须把实际归一化、分词与聚合代码一起固定下来。</p><h2 id="复现前先绑定哪些版本" tabindex="-1">复现前先绑定哪些版本？ <a class="header-anchor" href="#复现前先绑定哪些版本" aria-label="Permalink to &quot;复现前先绑定哪些版本？&quot;">​</a></h2><p>我们的建议是，把论文、代码提交、提示词、数据划分、评分函数及聚合脚本作为一组版本身份保存。检查输出时，分别记录样本总数、缺失数、条件质量、通信口径和效率分母。若报告计算成本，还要区分传输的消息与完整生成开销；本次没有运行模型，不能提供端到端成本结论。</p><p>这份札记采用较窄的证据门槛：论文和配套源码来自同一研究项目，是不同材料形态，不能算两份独立验证。公开一手事实只说明论文和仓库写了什么；内部实验依据只说明我们用合成输入执行的原函数及语句得到什么。研究解释连接两者，但不升级为论文表格有错或框架优劣判断。</p><h2 id="哪些影响仍然未知" tabindex="-1">哪些影响仍然未知？ <a class="header-anchor" href="#哪些影响仍然未知" aria-label="Permalink to &quot;哪些影响仍然未知？&quot;">​</a></h2><p>主要公开材料为研究团队的<a href="https://arxiv.org/html/2610.04672" target="_blank" rel="noreferrer">论文预印本，2610.04672v1，2026-10-03</a>与上述 <a href="https://github.com/BUPT-GAMMA/MASBench/tree/c0301a650db95958924bb080192c09fef39389a5" target="_blank" rel="noreferrer">c0301a6 源码版本</a>。内部执行环境为 Windows（操作系统）11、Python（程序设计语言）3.13.15。只抽取原函数与聚合语句、提供必要标准库环境，没有执行完整推理运行器、语言模型、数据集或论文表格。本阶段也没有新增实验。</p><p>究竟哪一版代码、提示词和聚合程序生成了论文表格，现有材料尚未建立完整对应。实际差异会影响多少数值、是否改变排序，也仍未知。发表、引用或源码能运行都不能补齐这个绑定；应先找到生成表格的确切工件，再讨论效应大小。</p>',20))])}const f=o(s,[["render",l]]);export{_ as __pageData,f as default};
